from lib import *
S = SS('w19')
steps = [
    step("STUN 绑定请求:向公网 STUN 服务器发一个 UDP 包,服务器把它看到的源地址和端口回给你。本机套接字的地址是私有的局域网地址,本地端口 56336;三个不同的 STUN 服务器看到的都是公网地址(公网 IP 是本机出口地址,不写出来),它们互相相同,端口也都是 56336。同一个本地套接字发往三个不同的目的地,映射到同一个外部地址和端口——这叫“与目的无关的映射”(endpoint-independent mapping);端口没有被改(端口保留)。服务器看到的公网地址与本机地址不同,说明路径上确实有 NAT。", t=tl(S(1)), mark=lidx(S(1), '服务器 1看到的', '服务器 2看到的', '服务器 3看到的'), done=lidx(S(1), '本机套接字', '3 个服务器有回应', '同一个本地套接字', '服务器看到的端口'), b=bars([['本地端口', 56336, '56336'], ['服务器 1 看到', 56336, '56336'], ['服务器 2 看到', 56336, '56336'], ['服务器 3 看到', 56336, '56336']], 56336, mark=[1, 2, 3], done=[0]), kv=KV([['本机地址', '私有(局域网)'], ['服务器看到的地址', '公网,3 个服务器一致'], ['外部端口', '= 本地端口 56336(端口保留)'], ['映射方式', '与目的无关']], ['映射方式'])),
    step("端口保留是不是总成立:40 个本地端口不同的 UDP 套接字(随机端口加几个固定端口,包括 4500)各发一次 STUN,外部端口与本地端口相同的有 39 个、不同的 1 个、没有回应的 0 个。不同的那个是本地端口 4500,被映射到 3319(4500 是 IPsec NAT 穿越常用的端口,这里只看到现象,为什么没保留没有验证)。TCP 方面三个 STUN 服务器都没有回应 TCP 上的 STUN 请求,所以 TCP 的映射在这个实验里没有测到。", t=tl(S(2)), mark=lidx(S(2), 'UDP:40 个套接字'), done=lidx(S(2), 'TCP 服务器 1', 'TCP 服务器 2', 'TCP 服务器 3'), b=bars([['端口保留', 39, '39'], ['端口被改', 1, '1(4500 → 3319)'], ['没有回应', 0, '0']], 40, mark=[1], done=[0, 2]), kv=KV([['40 个 UDP 套接字', '39 个保留端口'], ['本地 4500', '映射成 3319'], ['TCP', 'STUN 服务器不支持,没有测到']], ['本地 4500'])),
    step("能不能用 traceroute 看出 NAT 在哪一跳?UDP 探测从固定本地端口发出,TTL 1~16,有 10 个 TTL 有回应(第 1、2、3、4、5、7、9、10、14、15 跳),每一跳超时报文里引用的原包头源地址都是本机局域网地址、源端口都和本机发出的相同。也就是说连很远的跳也看不到被改写的源地址,而第一节明明显示服务器看到的是公网地址。我的解释是 NAT 设备把差错报文送回内网时,把内嵌的原包头也翻译回了内网地址(这样内网主机才认得出这是自己的包)——这个解释没有直接验证。结论:用这种方法看不出 NAT 位于哪一跳。", t=tl(S(3)), mark=lidx(S(3), '第一节明明显示', '16 个 TTL 里'), done=lidx(S(3), 'TTL=1:', 'TTL=2:', 'TTL=3:', 'TTL=4:', 'TTL=14:'), b=bars([['有回应的 TTL', 10, '10 / 16'], ['引用的源地址 = 本机内网地址', 10, '10'], ['引用的源地址 = 别的地址', 0, '0']], 16, mark=[1], done=[0, 2]), kv=KV([['10 个有回应的跳', '引用的源地址都是内网地址'], ['原因(推测)', 'NAT 翻译了内嵌的原包头'], ['结论', 'traceroute 看不出 NAT 的位置']], ['原因(推测)'])),
    step("NAPT 表的纸面模型(模拟,不是实测),公网地址 203.0.113.1:5 个内网连接各得到一条记录。10.0.0.2 和 10.0.0.3 都用 UDP 源端口 5000:第一个映射到外部端口 5000(保留),第二个因为 5000 已被占用换成 40000;两台主机 TCP 都用源端口 52111,同样一个保留、一个换成 40001。回程翻译:来自 198.51.100.7:53 发往 5000 的包翻译回 10.0.0.2:5000;来自没联系过的 198.51.100.99:53 的包、发往没有记录的端口 41234 的包,都被丢弃。改写源地址 10.0.0.2 → 203.0.113.1 之后,IP 头校验和用增量公式得 0xd473,与整头重算一致(TCP / UDP 的校验和还要同样更新,因为伪头部含地址)。", t=tl(S(4)), mark=lidx(S(4), 'udp 10.0.0.3', 'tcp 10.0.0.4', '回程翻译'), done=lidx(S(4), 'udp 10.0.0.2:5000 → 198.51.100.7', 'tcp 10.0.0.2', 'NAT 表里', '改写源地址'), kv=KV([['记录', '(协议, 内网地址:端口, 目的) → 外部端口'], ['端口冲突', '换一个新的外部端口(40000 起)'], ['入站', '没有记录或来源不符 → 丢弃'], ['校验和', '改地址、端口都要增量更新']], ['入站'])),
]
A = mkartw('w19', 19, '网络协议,NAT,NAPT,STUN,端口映射,端口保留,真实验证,动画演示',
    '用 STUN 实测本机出口的 NAT:外部看到的是公网地址、端口保留,与目的无关的映射;40 个套接字里 39 个保留端口(4500 被改成 3319);traceroute 看不到被改写的源地址;NAPT 表的纸面模型演示端口冲突、入站过滤和校验和更新。',
    '家里的设备都用私有地址,怎么和公网通信?NAT 到底改了什么,端口会不会变?这篇用 STUN 服务器问“你看到我的源地址和端口是什么”,实测本机出口 NAT 的映射行为,再用一个纸面模型演示 NAPT 表。',
    [('56336 = 56336', '本机 UDP 本地端口与 STUN 服务器看到的外部端口相同(端口保留),三个服务器看到的一致'), ('39 / 40', '40 个 UDP 套接字里外部端口与本地端口相同的个数;唯一不同的是本地 4500 → 3319'), ('10 / 10', '路径上有回应的 10 个跳,引用的源地址全是本机局域网地址——traceroute 看不出 NAT 位置')],
    [('STUN 看到的', '<p>STUN 服务器把收到的 UDP 包的源地址和端口回给你。实测:本机地址是私有的,服务器看到公网地址,端口不变,三个服务器看到的一样,是“与目的无关的映射”。</p>'),
     ('端口保留', '<p>40 个 UDP 套接字里 39 个外部端口等于本地端口,只有本地 4500 被改成 3319,原因没有验证;TCP 的 STUN 服务器没有回应,TCP 映射没有测到。</p>'),
     ('traceroute 看不见 NAT', '<p>路径上远处路由器回的超时报文引用的源地址仍是内网地址,推测是 NAT 把内嵌的原包头翻译了回去。所以不能靠 traceroute 判断 NAT 在哪一跳。</p>'),
     ('NAPT 表', '<p>纸面模型:每个内网连接对应一条记录,优先保留源端口,冲突时分配新端口;入站包必须匹配记录才被翻译,否则丢弃;改地址或端口时用增量公式更新校验和。</p>')],
    steps,
    [ENV_W + '。STUN 服务器是三个公网服务器(Cloudflare、Twilio、小米),只用来问“你看到我的地址”;本机的公网出口地址不写出来,只比较是否相同;第四节是纸面模型,地址为文档地址与私有地址,不是实测',
     '没有验证:TCP 的 NAT 映射(STUN 服务器不支持 TCP);UDP 映射的空闲超时(端口保留使“换端口”无法作为到期信号);入站过滤类型(全锥 / 受限 / 端口受限 / 对称的区分);发夹(hairpin)NAT;NAT 所在的位置与是否多层;其它端口是否也不被保留'],
    'NAT 与 NAPT')
